def find_groups_with_details(grid):
    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    groups = []

    def dfs(r, c, group_id):
        stack = [(r, c)]
        while stack:
            cr, cc = stack.pop()
            if visited[cr][cc]:
                continue
            visited[cr][cc] = True
            group_id.append((cr, cc))
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = cr + dr, cc + dc
                if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc]:
                    if grid[nr][nc] == 5:
                        stack.append((nr, nc))

    current_group = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 5 and not visited[r][c]:
                current_group = []
                dfs(r, c, current_group)
                if current_group:
                    groups.append(current_group)

    return groups

