# Check connectivity - can we reach from here to somewhere far away?
def is_connected_to_border(p, grid, target_value):
    r, c = p
    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]

    queue = [(r, c)]
    can_reach = False
    for br in [0, rows-1]:
        for bc in [0, cols-1]:
            if (br, bc) not in visited and ((br, bc) == (r, c)):
                can_reach = True
                break

    # BFS to see all reachable cells with same value
    for start_r in [0, rows-1]:
        for start_c in [0, cols-1]:
            if grid[start_r][start_c] == target_value:
                bfs_queue = [(start_r, start_c)]
                seen = {(start_r, start_c)}
                while bfs_queue:
                    cr, cc = bfs_queue.pop()
                    if (cr, cc) == (r, c):
                        can_reach = True
                        break
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in seen and grid[nr][nc] == target_value:
                            seen.add((nr, nc))
                            bfs_queue.append((nr, nc))
                if can_reach:
                    break
        if can_reach:
            break

    return can_reach

