# Let me check if there's something about row/col spans or whether a cell is part of longer line segments
def analyze_line_segments(grid):
    rows, cols = len(grid), len(grid[0])

    # Horizontal: for each row, find consecutive runs of same value
    horizontal_runs = []
    for r in range(rows):
        c = 0
        while c < cols:
            if grid[r][c] == 4:
                start = c
                while c < cols and grid[r][c] == 4:
                    c += 1
                end = c - 1
                length = end - start + 1
                horizontal_runs.append((r, start, end, length))
            else:
                c += 1

    # Vertical: for each column, find consecutive runs of same value
    vertical_runs = []
    for c in range(cols):
        r = 0
        while r < rows:
            if grid[r][c] == 4:
                start = r
                while r < rows and grid[r][c] == 4:
                    r += 1
                end = r - 1
                length = end - start + 1
                vertical_runs.append((start, end, length))
            else:
                r += 1

    return horizontal_runs, vertical_runs

