# Maybe: remove cells that are on the edge of a group? Like a skeletonization?
def compute_skeleton(grid):
    rows, cols = len(grid), len(grid[0])
    skeleton = [[False]*cols for _ in range(rows)]

    # A cell is on skeleton if removing it doesn't disconnect the component
    # This is hard to compute exactly, so let's approximate

    # For now, just mark interior cells as non-skeleton
    visited = set()
    stack = [(r,c) for r in range(rows) for c in range(cols) if grid[r][c] == 4]

    while stack:
        r, c = stack.pop()
        if (r,c) in visited:
            continue
        visited.add((r,c))

        # Check all neighbors
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if grid[nr][nc] == 4 and (nr, nc) not in visited:
                        stack.append((nr, nc))

    # Now, for each cell in visited, mark as non-edge if it has same-valued neighbors
    # in multiple directions
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 4:
                nbs = []
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 4:
                            nbs.append((nr, nc))

                # If cell has neighbors in both row AND column directions, it's interior
                row_neighbor = any((r, cc) in nbs for _, cc in nbs)
                col_neighbor = any((rr, c) in nbs for rr, _ in nbs)

                if row_neighbor and col_neighbor:
                    skeleton[r][c] = True

    return skeleton

